const SHARED_IPV6_PREFIX_NAME = 'perf-ipv6-shared';
const IPV6_POOL_USER_ROLE = 'perf-ipv6-shared-pool-user';
const IPV6_MIN_LEN = 40;
const IPV6_MAX_LEN = 56;

